import math

K_B = 8.617e-5

def miscibility_edge(omega, T):
    if omega <= 2 * K_B * T:
        return None
    f = lambda x: K_B * T * math.log(x / (1 - x)) - omega * (2 * x - 1)
    lo, hi = 1e-15, 0.5 - 1e-12
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if f(mid) < 0:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)

